window.mountKnowledgeExercise=function(id,host){const questions=window.knowledgeQuestions[id];if(!questions?.length)throw new Error('Övningen saknar frågor: '+id);let index=0,score=0;const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const q=questions[index];host.innerHTML=`<div class="knowledge-progress"><span>Fråga ${index+1} av ${questions.length}</span><span>Poäng: ${score}</span></div>${q.context?`<blockquote class="question-context">${esc(q.context)}</blockquote>`:''}<p class="question">${esc(q.q)}</p><div class="knowledge-options" role="radiogroup" aria-label="Svarsalternativ">${q.options.map((o,i)=>`<button type="button" role="radio" aria-checked="false" data-answer="${i}">${esc(o)}</button>`).join('')}</div><div class="actions"><button class="primary" id="knowledge-check" disabled>Kontrollera svar</button><button id="knowledge-next" hidden>${index===questions.length-1?'Visa resultat':'Nästa fråga'}</button></div><div id="feedback" class="feedback" aria-live="polite"></div><div id="knowledge-visual" class="knowledge-visual" hidden></div>`;let selected=null;host.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.answer);host.querySelectorAll('[data-answer]').forEach(x=>x.setAttribute('aria-checked',String(x===b)));document.getElementById('knowledge-check').disabled=false;});document.getElementById('knowledge-check').onclick=()=>{if(selected===null)return;const ok=selected===q.answer;if(ok)score++;host.querySelectorAll('[data-answer]').forEach((b,i)=>{b.disabled=true;b.classList.toggle('answer-correct',i===q.answer);b.classList.toggle('answer-wrong',i===selected&&i!==q.answer);});const f=document.getElementById('feedback');f.textContent=(ok?'Rätt. ':'Inte riktigt. ')+q.why;f.classList.toggle('wrong',!ok);const v=document.getElementById('knowledge-visual');v.textContent=q.visual;v.hidden=false;document.getElementById('knowledge-check').hidden=true;document.getElementById('knowledge-next').hidden=false;};document.getElementById('knowledge-next').onclick=()=>{if(++index<questions.length)render();else finish();};}function finish(){host.innerHTML=`<div class="knowledge-result"><p class="eyebrow">Övningen är klar</p><h2>${score} av ${questions.length} rätt</h2><p>${score===questions.length?'Alla rätt. Bra arbetat!':'Gör gärna om övningen och försök igen.'}</p><button class="primary" id="knowledge-restart">Gör om övningen</button></div>`;document.getElementById('knowledge-restart').onclick=()=>{index=0;score=0;render();};}render();};
